/**
 * LoginSound — plays a short chime on every admin login (Phase —
 * Super Admin login sound).
 *
 * WHEN IT PLAYS
 * -------------
 * Only right after a SUCCESSFUL Auth.login() call on the login page, before
 * the redirect to the admin home. It never plays on a page reload, on
 * requireAuth() re-checks, or on any other protected-page load — those all
 * read an EXISTING session, not a new sign-in, so LoginSound.play() is
 * only ever called from login.js. Since play() is only ever reached on
 * an actual sign-in (never on reload/navigation), it plays EVERY time,
 * including logout-then-login-again in the same tab: no sessionStorage
 * guard is needed to get "once per login".
 *
 * OFF SWITCH
 * ----------
 * The on/off preference is a genuine cross-session UI preference — "never
 * play this for me" should survive closing the browser — so it lives in
 * localStorage under one key, read by both this module and the Settings
 * page. Purely a client-side UX preference, no server value, no security
 * implication.
 *
 * ASSET
 * -----
 * Inlined as a base64 data: URI so no extra network request/asset path is
 * needed and the login page never depends on a CDN or static file that
 * could 404. ~15KB source, ~1.8s duration.
 */

const LoginSound = (() => {
  const ENABLED_KEY = "tnc_admin_sound_enabled";

  const CHIME_SRC = "data:audio/mpeg;base64,";

  function isEnabled() {
    try {
      const v = localStorage.getItem(ENABLED_KEY);
      return v === null ? true : v === "1"; // default ON
    } catch {
      return true;
    }
  }

  function setEnabled(enabled) {
    try {
      localStorage.setItem(ENABLED_KEY, enabled ? "1" : "0");
    } catch {
      /* storage disabled: preference just cannot persist */
    }
  }

  /**
   * Plays the chime, unless the admin has turned it off.
   *
   * Returns a Promise that resolves when the sound has FINISHED playing (or
   * failed / was blocked / timed out). login.js awaits it before redirecting:
   * navigating away destroys the Audio object, so redirecting immediately
   * after play() cuts the chime off before it is ever heard.
   *
   * The promise NEVER rejects and always settles within MAX_WAIT_MS, so a
   * sound problem (autoplay block, decode error, storage failure) can never
   * delay or block sign-in.
   */
  const MAX_WAIT_MS = 2500; // chime is ~1.8s; hard cap so login never hangs

  function play() {
    if (!isEnabled()) return Promise.resolve();

    return new Promise((resolve) => {
      let settled = false;
      const done = () => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        resolve();
      };
      const timer = setTimeout(done, MAX_WAIT_MS);

      try {
        const audio = new Audio(CHIME_SRC);
        audio.volume = 0.6;
        audio.addEventListener('ended', done, { once: true });
        audio.addEventListener('error', done, { once: true });
        const started = audio.play();
        if (started && typeof started.catch === 'function') {
          started.catch(done); // autoplay blocked: do not wait for a sound that will never play
        }
      } catch {
        done(); // ignore: sound is a nice-to-have, never load-bearing
      }
    });
  }

  return { isEnabled, setEnabled, play };
})();